def tall(html, h):
    return html.replace("<td></td>", f'<td style="height:{h}mm"></td>')


def compact(html):
    return html.replace('class="t"', 'class="t compact"')


def P_(t):
    return "".join(f'<p style="margin:0 0 1.1mm 0;text-indent:5mm">{x}</p>' for x in t.strip().split("\n"))


def nouvelle(titre, part, html, fs=10):
    return (f'<div class="card" style="{SERIF};background:#FFFCF5;border:1.5px solid #d8c9a8;font-size:{fs}pt;padding:3mm 4.5mm">'
            f'<div class="flex" style="justify-content:space-between;margin-bottom:1mm;font-family:Poppins"><span>{F} <b style="color:{MC}">{titre}</b> <span class="xs muted">{part}</span></span><span class="xs muted">nouvelle écrite pour la classe</span></div>{html}</div>')


BUS1 = P_("""Ce soir-là, Nadia sortit de la bibliothèque à dix-neuf heures passées. Il pleuvait sur Hautrive depuis le matin, une pluie fine et froide de novembre. Les rues étaient désertes et les réverbères dessinaient des cercles jaunes sur les trottoirs mouillés. Nadia remonta la capuche de son anorak et courut jusqu'à l'arrêt.
Elle consulta l'horaire : le dernier bus pour Valmont passait à 19 h 12. Il était 19 h 10. Elle respira. Deux minutes, ce n'était rien.
Sur le banc de l'abribus, un vieil homme était assis. Il portait un long manteau gris, beaucoup trop grand pour lui, et un chapeau d'un autre temps. Il tenait sur ses genoux une petite valise en cuir. Nadia lui sourit poliment. Il ne répondit pas. Il regardait la rue, immobile, comme une statue.
19 h 12. Pas de bus. 19 h 15. Toujours rien. Nadia sortit son téléphone : plus de batterie. Elle soupira.""")
BUS2 = P_("""— Il ne viendra pas, dit soudain le vieil homme.
Sa voix était rauque, comme si elle n'avait pas servi depuis longtemps. Nadia sursauta.
— Pardon ?
— Le bus de 19 h 12. Il ne viendra pas. Il ne vient jamais le mardi.
Nadia fronça les sourcils. On était bien mardi. Mais l'horaire, affiché derrière la vitre, indiquait clairement : « du lundi au vendredi ».
— Vous l'attendez aussi ? demanda-t-elle.
— Depuis longtemps, murmura-t-il. Très longtemps.
Un frisson parcourut le dos de Nadia. Au loin, une lumière apparut au bout de la rue, puis deux phares. Un bus ! Il s'approcha lentement, sans bruit, et s'arrêta devant l'abribus. Mais ce n'était pas le bus bleu habituel : c'était un vieux bus vert et crème, aux vitres embuées, comme on en voit sur les photos anciennes. Sur le panneau, on lisait : « Valmont – 1962 ». Les portes s'ouvrirent dans un grincement.""")
BUS3 = P_("""Le vieil homme se leva, serra sa valise contre lui et se tourna vers Nadia.
— Ne montez pas, mademoiselle. Ce bus n'est pas pour vous.
Il monta. Les portes se refermèrent. Le bus repartit et disparut dans la pluie, comme s'il s'était dissous dans la nuit.
Nadia resta seule, le cœur battant. Cinq minutes plus tard, le bus bleu arriva, en retard, comme tous les soirs. Le chauffeur s'excusa : un accident avait bloqué la rue Haute.
Le lendemain, Nadia raconta tout à sa grand-mère. La vieille dame pâlit. Elle alla chercher une boîte à chaussures pleine de photos et en sortit une, jaunie, découpée dans un journal.
— Ton arrière-grand-père, Ahmed, dit-elle doucement. Il est arrivé à Hautrive en 1962 pour travailler à l'usine. Le premier soir, il a raté le dernier bus pour Valmont, et il a dû dormir dans la gare. Il disait toujours en riant : « Un jour, je l'attraperai, ce bus ! »
Sur la photo, un jeune homme souriait. Il portait un long manteau gris et tenait à la main une petite valise en cuir.""")

COLIS = P_("""Depuis une semaine, Léo attendait le colis. Il avait économisé pendant six mois pour s'acheter un casque de réalité virtuelle, le même que celui de son cousin. Chaque jour, en rentrant de l'école, il vérifiait le suivi de commande : « En cours de livraison ».
Mercredi, enfin, la sonnette retentit. Léo dévala l'escalier. Sur le paillasson, il n'y avait personne. Seulement un carton, beaucoup plus petit que prévu, sans nom ni adresse. Il le ramassa : il était léger, si léger qu'il semblait vide. Bizarre.
Dans sa chambre, il ouvrit le carton avec des ciseaux, les mains tremblantes. À l'intérieur, sous du papier de soie, il trouva… une vieille enveloppe et une clé rouillée. Sur l'enveloppe, une écriture qu'il connaissait : celle de son grand-père, mort deux ans plus tôt. « Pour Léo, quand il aura quinze ans. »
Léo avait eu quinze ans le matin même. Il avait cru que tout le monde avait oublié.
Il ouvrit l'enveloppe. « Mon grand, cette clé ouvre le grenier de la maison de Bastogne. Tout ce qu'il y a là-haut est à toi. Tu verras, c'est mieux qu'un casque. Ton grand-père qui t'aime. »
Le soir, sa mère rentra avec un grand sourire et un paquet sous le bras : le casque de réalité virtuelle. Léo la remercia… puis il lui montra la clé. Elle se mit à pleurer. Le samedi suivant, ils prirent la route de Bastogne.
Dans le grenier, sous une bâche, attendaient une table de bois, une boîte de couleurs, des pinceaux et des dizaines de carnets remplis de dessins de forêts, de rivières et de maisons. Le grand-père de Léo avait été peintre, et personne ne l'avait jamais su.""")


def schema(fill=None, quiz=False):
    """Schéma narratif en 5 étapes (fill = textes ; quiz = cases vides)."""
    steps = [("① Situation initiale", "Qui ? Où ? Quand ? La vie est calme.", "#9B8FC7"), ("② Élément déclencheur", "Un événement change tout.", "#E4572E"), ("③ Péripéties", "Les actions, les obstacles, le suspense.", "#F29E4C"),
             ("④ Dénouement", "Le problème est résolu (ou pas).", "#2BA88F"), ("⑤ Situation finale", "La nouvelle situation, la chute.", "#4A7BD1")]
    out = ""
    for i, (t, d, c) in enumerate(steps):
        txt = fill[i] if fill else ("" if quiz else d)
        out += (f'<div style="flex:1;display:flex;flex-direction:column"><div style="background:{c};color:#fff;font-weight:700;font-size:9pt;padding:1.5mm 2mm;border-radius:2mm 2mm 0 0;text-align:center">{t}</div>'
                f'<div class="xs" style="border:1.5px solid {c};border-top:none;border-radius:0 0 2mm 2mm;padding:1.5mm 2mm;min-height:{26 if quiz else 14}mm;background:#fff">{txt}</div></div>')
        if i < 4:
            out += '<div style="align-self:center;font-size:14pt;color:#9aa1b1">➜</div>'
    return f'<div class="flex top" style="gap:1mm;align-items:stretch">{out}</div>'


def tension(pts=None, w=176, labels=None):
    """Courbe de tension d'un récit (suspense)."""
    labels = labels or ["situation initiale", "déclencheur", "péripéties", "point culminant", "dénouement", "fin"]
    X = lambda k: 40 + k * 104
    Y = lambda v: 140 - v * 24
    o = [f'<line x1="30" y1="140" x2="580" y2="140" stroke="#1F2A44" stroke-width="1.5"/><line x1="30" y1="140" x2="30" y2="10" stroke="#1F2A44" stroke-width="1.5"/><text x="34" y="18" font-size="11" font-weight="700">tension ↑</text>']
    for k, l in enumerate(labels):
        o.append(f'<text x="{X(k)}" y="156" font-size="10.5" text-anchor="middle">{l}</text>')
    if pts:
        o.append(f'<polyline points="{" ".join(f"{X(k)},{Y(v)}" for k, v in enumerate(pts))}" fill="none" stroke="{MC}" stroke-width="3"/>' + "".join(f'<circle cx="{X(k)}" cy="{Y(v)}" r="5" fill="{MC}"/>' for k, v in enumerate(pts)))
    else:
        o.append("".join(f'<circle cx="{X(k)}" cy="{Y(v)}" r="3" fill="#cfd4dc"/>' for k in range(6) for v in range(6)))
    return f'<svg viewBox="0 0 590 164" width="{w}mm" style="max-width:100%;height:auto" font-family="Poppins" fill="#1F2A44">{"".join(o)}</svg>'


