    e2 = E("Après le jeu : je note les 4 cartes de mon histoire préférée et j'écris sa première phrase.", lines(2), ["ecris"], 2, "C", sol="Production personnelle : quatre éléments, une première phrase qui situe (qui, où, quand).")
    e3 = E("Défi ! J'écris en 5 phrases l'histoire inventée avec mes cartes, avec une chute.", lines(5), ["ecris"], 3, "C", sol="Récit court : quatre éléments, schéma narratif, chute, temps du passé.")
    b.page(f'{atl_head("D", "Atelier · Les dés à histoires")}{e}{e2}{e3}', "Atelier")

    # ---------- ★ Coup de pouce ----------
    e = E("Je relie le mot et le dessin.", relie(["un bus", "la pluie", "une valise", "une clé", "un chapeau"], ["🔑", "🧳", "🚌", "🎩", "🌧️"]), ["relie"], 1, "B", alpha=True, sol="bus → 🚌 · pluie → 🌧️ · valise → 🧳 · clé → 🔑 · chapeau → 🎩")
    e2 = E("Je remets l'histoire dans l'ordre : 1, 2, 3, 4.", '<div class="card big" style="line-height:2">___ Le vieil homme monte dans le bus. &nbsp; ___ Nadia attend le bus.<br>___ Un vieux bus arrive. &nbsp; ___ Nadia voit une photo de son arrière-grand-père.</div>', ["lis", "numerote"], 1, "B", alpha=True, sol="3 · 1 · 2 · 4")
    e3 = E("Je complète avec : D'abord · Ensuite · Soudain · À la fin.", '<div class="card" style="background:#F2F6FD"><p class="big" style="line-height:2.1;margin:0">______________, Léo attend un colis.<br>______________, il ouvre le carton.<br>______________, il trouve une clé !<br>______________, il découvre les dessins de son grand-père.</p></div>', ["complete"], 1, "C", alpha=True, sol="D'abord · Ensuite · Soudain · À la fin")
    b.page(CP.format(t="L'histoire dans l'ordre") + e + e2 + e3, "★ Coup de pouce")
    e = E("Je lis le modèle. Je complète avec l'imparfait (décor).", '<div class="card" style="background:#F2F6FD"><p class="big" style="margin:0">Modèle : Il <b>pleuvait</b>. La rue <b>était</b> vide.</p></div><p class="big" style="line-height:2.1;margin:2mm 0 0">1. Il (faire) ______________ froid.<br>2. Le ciel (être) ______________ noir.<br>3. Nadia (avoir) ______________ peur.</p>', ["lis", "complete"], 1, "C", alpha=True, sol="1. faisait — 2. était — 3. avait")
