    b.page(CP.format(t="Imparfait et passé simple") + e + e2 + e3, "★ Coup de pouce")
    e = E("Je relie le sens et la phrase.", relie(["👀 la vue", "👂 l'ouïe", "👃 l'odorat", "✋ le toucher"], ["La porte grince.", "Ça sent le pain chaud.", "La lune est blanche.", "La pluie est froide."]), ["relie"], 1, "B", alpha=True, sol="vue → la lune est blanche · ouïe → la porte grince · odorat → ça sent le pain chaud · toucher → la pluie est froide")
    e2 = E("J'ajoute un adjectif : une maison ______________ · un homme ______________ · une nuit ______________ · un chat ______________", "", ["complete"], 1, "C", alpha=True, sol="Ex. : vieille · grand · noire · noir")
